// Página da ponte: PC online?, pedir uma ação e acompanhar.
// ── Moldura das páginas (mesmo visual em todos os fluxos grátis) ──
function pagina(titulo, corpo, script) {
  const css = `
:root{--fundo:#f6f5f2;--cartao:#fff;--texto:#1d1d1b;--suave:#6b6b66;--linha:#e3e1db;--acento:#0f766e;--acento2:#115e59;--erro:#b42318;--ok:#067647}
@media (prefers-color-scheme:dark){:root{--fundo:#121412;--cartao:#1b1e1c;--texto:#ecebe7;--suave:#a3a39d;--linha:#2c302d;--acento:#2dd4bf;--acento2:#5eead4;--erro:#f97066;--ok:#47cd89}}
*{box-sizing:border-box}body{margin:0;background:var(--fundo);color:var(--texto);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:20px 16px 48px}h1{font-size:1.45rem;margin:.2em 0 .1em}h2{font-size:1.1rem;margin:1.2em 0 .5em}
.sub{color:var(--suave);margin:0 0 18px}.cartao{background:var(--cartao);border:1px solid var(--linha);border-radius:14px;padding:16px;margin:12px 0}
label{display:block;font-weight:600;margin:12px 0 6px}textarea,input,select{width:100%;padding:11px 12px;border:1px solid var(--linha);border-radius:10px;background:var(--fundo);color:var(--texto);font:inherit}
textarea{min-height:120px;resize:vertical}.linha{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
button,.botao{display:inline-block;background:var(--acento);color:#fff;border:0;border-radius:10px;padding:12px 18px;font:600 1rem system-ui,sans-serif;cursor:pointer;text-decoration:none;margin-top:14px}
@media (prefers-color-scheme:dark){button,.botao{color:#04211e}}
button[disabled]{opacity:.55;cursor:wait}.botao.sec{background:transparent;color:var(--acento);border:1px solid var(--acento)}
.aviso{color:var(--suave);font-size:.9rem}.erro{color:var(--erro);font-weight:600}.ok{color:var(--ok);font-weight:600}
.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.grade img,.grade video{width:100%;border-radius:10px;border:1px solid var(--linha);background:#000}
video,audio{width:100%;margin-top:10px;border-radius:10px}pre{white-space:pre-wrap;background:var(--fundo);border:1px solid var(--linha);border-radius:10px;padding:12px;font-size:.9rem}
.barra{height:8px;background:var(--linha);border-radius:99px;overflow:hidden;margin:10px 0}.barra i{display:block;height:100%;background:var(--acento);width:0;transition:width .6s}
.selo{display:inline-block;font-size:.78rem;border:1px solid var(--linha);border-radius:99px;padding:2px 9px;color:var(--suave);margin:2px 4px 2px 0}
footer{color:var(--suave);font-size:.82rem;margin-top:28px}`;
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="robots" content="noindex"><title>' + titulo + '</title><style>' + css + '</style></head><body><main>' + corpo +
    '<footer>Feito com serviços grátis e sem chave (Hugging Face, Pollinations, Bing/Google Tradutor). Pode demorar ou falhar quando eles estão cheios.</footer>' +
    '</main>' + (script ? '<script>' + script + '</script>' : '') + '</body></html>';
}
const escHtml = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let visto = null;
try { visto = JSON.parse($input.first().json.visto || 'null'); } catch (e) { visto = null; }
const ACOES = {"saude": "Saúde do PC (memória, disco, hora)", "imagem_flow": "Imagem no Google Flow / Nano Banana (contas do PC, 0 crédito)", "montar_video": "Montar vídeo no ffmpeg do PC (filme da fábrica grátis: vertical ou deitado)", "guardar_para_postar": "Guardar vídeo na caixa de saída do PC (os postadores postam com aprovação)"};
const online = visto && Date.now() - Date.parse(visto.quando) < 3 * 60e3;
const corpo = `
<h1>🌉 Ponte PC ↔ n8n</h1>
<p class="sub">O n8n deixa o pedido numa fila; o trabalhador do PC busca, faz com os geradores que já existem no PC
(Flow/Nano Banana, ffmpeg...) e devolve o resultado. Sem abrir porta no PC e sem instalar nada no servidor.</p>
<div class="cartao"><b>PC:</b> ${online ? '<span class="ok">online</span> (' + escHtml(visto.maquina) + ', visto ' +
  new Date(visto.quando).toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo' }) + ')'
  : '<span class="erro">fora do ar</span>' + (visto ? ' (último sinal ' + new Date(visto.quando).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) + ')' : '') +
  ' — no PC: <code>D:\\hipercool-materiais\\fluxos-n8n\\ponte-pc\\LIGAR_PONTE.bat</code>'}</div>
<div class="cartao">
  <label for="token">Token da ponte</label><input id="token" type="password" placeholder="está em ponte-pc\\config.json no PC">
  <label for="acao">Ação</label><select id="acao">${Object.entries(ACOES).map(([k, v]) => '<option value="' + k + '">' + escHtml(v) + '</option>').join('')}</select>
  <label for="dados">Dados (JSON)</label><textarea id="dados">{"prompt": "casa moderna com placas solares, fim de tarde", "formato": "9:16"}</textarea>
  <button id="ir">Mandar para o PC</button>
  <p id="estado" class="aviso"></p>
  <div id="saida"></div>
</div>
<div class="cartao aviso">Outros fluxos: <code>POST /webhook/ponte-pc/pedido</code> com cabeçalho <code>X-Ponte-Token</code> e
<code>{"acao":"imagem_flow","dados":{...}}</code> → <code>{"id","status_url"}</code>; depois <code>GET /webhook/ponte-pc/status?id=</code>.</div>`;
const script = `
const $ = id => document.getElementById(id);
$('ir').onclick = async () => {
  let dados; try { dados = JSON.parse($('dados').value || '{}'); } catch (e) { $('estado').textContent = 'JSON dos dados inválido'; return; }
  $('ir').disabled = true; $('estado').className = 'aviso'; $('estado').textContent = 'Enviando...';
  try {
    const r = await fetch('ponte-pc/pedido', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Ponte-Token': $('token').value },
      body: JSON.stringify({ acao: $('acao').value, dados, origem: 'página' }) });
    const j = await r.json();
    if (!j.ok) throw new Error(j.erro || 'falhou');
    $('estado').textContent = 'Na fila (' + j.id + '). Esperando o PC...';
    const olha = async () => {
      const s = await (await fetch('ponte-pc/status?id=' + j.id, { cache: 'no-store' })).json();
      $('estado').textContent = 'Situação: ' + s.etapa + (s.maquina ? ' (' + s.maquina + ')' : '') + (s.mensagem ? ' — ' + s.mensagem : '');
      if (s.etapa === 'pronto' || s.etapa === 'erro') {
        $('estado').className = s.etapa === 'pronto' ? 'ok' : 'erro';
        if (s.arquivo) $('saida').innerHTML = /\\.(png|jpe?g|webp)$/.test(s.arquivo) ? '<img src="' + s.arquivo + '" style="max-width:100%;border-radius:10px">'
          : /\\.(mp4|webm)$/.test(s.arquivo) ? '<video controls src="' + s.arquivo + '"></video>' : '<a class="botao" href="' + s.arquivo + '">Baixar</a>';
        $('ir').disabled = false; return;
      }
      setTimeout(olha, 4000);
    };
    olha();
  } catch (e) { $('estado').className = 'erro'; $('estado').textContent = 'Não deu: ' + e.message; $('ir').disabled = false; }
};`;
return [{ json: { html: pagina('Ponte PC', corpo, script) } }];

// Recebe um pedido para o PC (de outro fluxo ou da página). Só ações conhecidas; exige o token da ponte.
const TOKEN = "16b91f15ba1d735cd0327b3764c39ed7";
const ACOES = {"saude": "Saúde do PC (memória, disco, hora)", "imagem_flow": "Imagem no Google Flow / Nano Banana (contas do PC, 0 crédito)", "montar_video": "Montar vídeo no ffmpeg do PC (filme da fábrica grátis: vertical ou deitado)", "guardar_para_postar": "Guardar vídeo na caixa de saída do PC (os postadores postam com aprovação)"};
const ent = $input.first().json;
const b = ent.body || {};
const h = ent.headers || {};
const base = (h['x-forwarded-proto'] || 'https') + '://' + (h['x-forwarded-host'] || h.host);
if (String(h['x-ponte-token'] || b.token || '') !== TOKEN) return [{ json: { ok: false, codigo: 401, erro: 'token da ponte errado' } }];
const acao = String(b.acao || '');
if (!ACOES[acao]) return [{ json: { ok: false, codigo: 400, erro: 'ação desconhecida: ' + acao + ' (use: ' + Object.keys(ACOES).join(', ') + ')' } }];
const id = (Date.now().toString(36) + Math.random().toString(36).slice(2, 6)).toLowerCase();
const pedido = { id, acao, dados: b.dados || {}, origem: String(b.origem || 'página').slice(0, 60), criado: new Date().toISOString() };
const status = { id, acao, descricao: ACOES[acao], etapa: 'na_fila', criado: pedido.criado, origem: pedido.origem };
return [{ json: { ok: true, id, pedido: JSON.stringify(pedido), status: JSON.stringify(status),
  status_url: base + '/webhook/ponte-pc/status?id=' + id } }];

// O PC pergunta se tem trabalho. Confere o token e marca o PC como "online" (para a página mostrar).
const TOKEN = "16b91f15ba1d735cd0327b3764c39ed7";
const ent = $input.first().json;
const h = ent.headers || {};
const q = ent.query || {};
const ok = String(h['x-ponte-token'] || q.token || '') === TOKEN;
const maquina = String(q.maquina || 'pc').replace(/[^a-z0-9-]/gi, '').slice(0, 30) || 'pc';
return [{ json: { ok, maquina, visto: JSON.stringify({ maquina, quando: new Date().toISOString(), versao: String(q.versao || '') }) } }];

// Devolve ao PC o próximo pedido da fila (ou "vazio") e prepara o status "o PC pegou".
const tirado = $input.first().json.pedido;
const maquina = $('🧩 Confere o PC').first().json.maquina;
if (!tirado) return [{ json: { vazio: true, resposta: JSON.stringify({ vazio: true }) } }];
let p = {};
try { p = typeof tirado === 'string' ? JSON.parse(tirado) : tirado; } catch (e) { return [{ json: { vazio: true, resposta: '{"vazio":true}' } }]; }
return [{ json: { vazio: false, id: p.id, resposta: JSON.stringify(p),
  status: JSON.stringify({ id: p.id, acao: p.acao, etapa: 'no_pc', maquina, pegou: new Date().toISOString(), criado: p.criado, origem: p.origem }) } }];

// O PC devolve o resultado: guarda o arquivo (se houver, até ~15 MB) e o status final com o link.
const TOKEN = "16b91f15ba1d735cd0327b3764c39ed7";
const ent = $input.first().json;
const b = ent.body || {};
const h = ent.headers || {};
const base = (h['x-forwarded-proto'] || 'https') + '://' + (h['x-forwarded-host'] || h.host);
if (String(h['x-ponte-token'] || b.token || '') !== TOKEN) return [{ json: { ok: false, codigo: 401, erro: 'token da ponte errado' } }];
const id = String(b.id || '').toLowerCase().replace(/[^a-z0-9]/g, '');
if (!id) return [{ json: { ok: false, codigo: 400, erro: 'sem id' } }];
let nome = '';
let b64 = '';
if (b.arquivo_b64) {
  const ext = String(b.extensao || 'bin').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 5) || 'bin';
  nome = id + '-resultado.' + ext;
  b64 = String(b.arquivo_b64);
  if (b64.length > 21e6) return [{ json: { ok: false, codigo: 413, erro: 'arquivo grande demais para a ponte (máx. ~15 MB)' } }];
}
const status = { id, acao: String(b.acao || ''), etapa: b.ok ? 'pronto' : 'erro', maquina: String(b.maquina || ''),
  terminou: new Date().toISOString(), mensagem: String(b.mensagem || '').slice(0, 1000), dados: b.dados || {},
  arquivo: nome ? base + '/webhook/ponte-pc/arquivo?id=' + nome : null };
return [{ json: { ok: true, id, nome, b64, tem_arquivo: !!nome, status: JSON.stringify(status) } }];

// Devolve o arquivo guardado no Redis (texto base64) como arquivo de verdade, para o webhook entregar.
const id = String(($('🔔 Arquivo do PC (GET)').first().json.query || {}).id || '');
const b64 = String($input.first().json.dado || '');
const TIPOS = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', mp3: 'audio/mpeg',
  mp4: 'video/mp4', webm: 'video/webm', json: 'application/json', txt: 'text/plain' };
const ext = (id.split('.').pop() || '').toLowerCase();
if (!/^[a-z0-9-]{4,80}\.[a-z0-9]{2,5}$/.test(id) || !b64 || !TIPOS[ext]) return [{ json: { existe: false } }];
const bin = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), id, TIPOS[ext]);
return [{ json: { existe: true }, binary: { data: bin } }];
